public string CountAndSayRecursive(int n)
{
    if (n == 1) return "1";
    var prev = CountAndSayRecursive(n - 1);
    var sb = new StringBuilder();
    int count = 1;
    for (int i = 1; i < prev.Length; i++)
    {
        if (prev[i] == prev[i - 1]) count++;
        else { sb.Append(count).Append(prev[i - 1]); count = 1; }
    }
    sb.Append(count).Append(prev[^1]);
    return sb.ToString();
}

public string CountAndSay(int n)
{
    string term = "1";
    for (int iter = 1; iter < n; iter++)
    {
        var sb = new StringBuilder();
        int count = 1;
        for (int i = 1; i < term.Length; i++)
        {
            if (term[i] == term[i - 1]) count++;
            else { sb.Append(count).Append(term[i - 1]); count = 1; }
        }
        sb.Append(count).Append(term[^1]);
        term = sb.ToString();
    }
    return term;
}
